import time
import functools
from typing import Callable, Any

# 带参数的装饰器：API速率限制
def rate_limit(calls: int = 5, period: int = 60) -> Callable:
    """限制函数在给定时间段内的调用次数"""
    def decorator(func: Callable) -> Callable:
        # 使用列表存储时间戳，以便在闭包中修改
        timestamps = []

        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> Any:
            now = time.time()
            # 移除过期的时间戳
            timestamps[:] = [t for t in timestamps if now - t < period]
            if len(timestamps) >= calls:
                raise RuntimeError(f"Rate limit exceeded: {calls} calls per {period}s")
            timestamps.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator

# 类装饰器：记录函数调用统计
class CallLogger:
    def __init__(self, func: Callable):
        functools.update_wrapper(self, func)
        self.func = func
        self.call_count = 0
        self.total_time = 0.0

    def __call__(self, *args, **kwargs) -> Any:
        start = time.time()
        result = self.func(*args, **kwargs)
        elapsed = time.time() - start
        self.call_count += 1
        self.total_time += elapsed
        print(f"{self.func.__name__} called {self.call_count} times, total time: {self.total_time:.3f}s")
        return result

# 使用示例
@rate_limit(calls=3, period=10)
@CallLogger
def fetch_data(url: str) -> str:
    """模拟API请求"""
    time.sleep(0.1)  # 模拟延迟
    return f"Data from {url}"

# 测试
if __name__ == "__main__":
    for i in range(5):
        try:
            result = fetch_data("https://api.example.com")
            print(f"Request {i+1}: {result}")
        except RuntimeError as e:
            print(f"Request {i+1}: {e}")
        time.sleep(1)  # 每次请求间隔1秒

